    # Deterministic constructive + repair + local-search CVRP solver
    # Assumes instance with:
    # - 'customer_ids': list of ints
    # - 'demands': dict mapping id -> int
    # - 'capacity': int
    # Optional: 'distance' ignored for feasibility

    customers = list(instance['customer_ids'])
    demand = dict(instance['demands'])
    capacity = instance['capacity']

    if not customers:
        return []

    customers.sort()  # deterministic order

    # Deterministic greedy constructive routing
    routes = []
    current_route = []
    current_load = 0

    for cid in customers:
        d = demand.get(cid, 0)
        if current_load + d <= capacity:
            current_route.append(cid)
            current_load += d
        else:
            if current_route:
                routes.append(current_route)
            current_route = [cid]
            current_load = d

    if current_route:
        routes.append(current_route)

    # Repair: ensure each customer appears exactly once
    seen = set()
    for r in routes:
        for c in list(r):
            if c in seen:
                r.remove(c)
            else:
                seen.add(c)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        for r in routes:
            load = sum(demand.get(x, 0) for x in r)
            if load + demand.get(c, 0) <= capacity:
                r.append(c)
                placed = True
                break
        if not placed:
            routes.append([c])

    # Local search: 1-move between routes to merge towards fewer routes
    changed = True
    while changed:
        changed = False
        for i in range(len(routes)):
            if not routes[i]:
                continue
            c = routes[i][-1]
            w = demand.get(c, 0)
            for j in range(len(routes)):
                if i == j or not routes[j]:
                    continue
